node --input-type=module -e "
let leaves = 0;
const NATIONALITIES = ['Englishman', 'Spaniard', 'Ukrainian', 'Norwegian', 'Japanese'];
const COLORS = ['Red', 'Ivory', 'Green', 'Yellow', 'Blue'];
const PETS = ['Dog', 'Fox', 'Snail', 'Horse', 'Zebra'];
const DRINKS = ['Coffee', 'Tea', 'Milk', 'Orange juice', 'Water'];
const HOBBIES = ['Dancing', 'Reading', 'Painter', 'Football', 'Chess'];
const houses = [0,1,2,3,4].map(() => ({}));
houses[0].nationality = 'Norwegian';
houses[2].drink = 'Milk';
const categories = ['nationality','color','pet','drink','hobby'];
const values = [NATIONALITIES, COLORS, PETS, DRINKS, HOBBIES];
const backtrack = (ci) => {
  if (ci === categories.length) { leaves++; return true; }
  const category = categories[ci];
  for (const value of values[ci]) {
    if (houses.some((h) => h[category] === value)) continue;
    const unassigned = houses.filter((h) => h[category] === undefined);
    for (const house of unassigned) {
      house[category] = value;
      if (backtrack(ci + 1)) return true;
      house[category] = undefined;
    }
  }
  return false;
};
console.log('found:', backtrack(0), 'leaves:', leaves);
console.log(JSON.stringify(houses, null, 1));
"

